function n(i,e,r,t){if(!Number.isFinite(i)||!Number.isFinite(e)||!Number.isFinite(r)||e<1||e>12||r<1||r>31)return null;switch(t){case"zh-TW":case"zh-HK":case"zh-CN":case"ja":return`${i}年${e}月${r}日`;case"ko":return`${i}년 ${e}월 ${r}일`;case"vi":return`${r} tháng ${e}, ${i}`;default:try{return new Intl.DateTimeFormat(t,{year:"numeric",month:"long",day:"numeric"}).format(new Date(i,e-1,r))}catch{return`${r}/${e}/${i}`}}}export{n as e};
